    createTemporalServer: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "name": "payments",
                 *       "plan": "dev"
                 *     }
                 */
                "application/json": components["schemas"]["CreateTemporalServerRequest"];
            };
        };
        responses: {
            /** @description Provisioning started */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["TemporalServer"];
                };
            };
            /** @description The body is not JSON, the name breaks the rule (lowercase letters, digits and `-`, starting with a letter and ending with a letter or digit), or PaaS refused the request (its message is passed through). */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["SubscriptionSuspended"];
            /** @description The organization already has a platform service with this name (PaaS's message). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description PaaS refused the plan or placement, for example a plan it does not offer or a plane without Temporal. Its message is passed through. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            429: components["responses"]["PaaSRateLimited"];
            502: components["responses"]["PaaSUpstreamError"];
            /** @description Temporal is not configured here, or the organization's first platform service is still waiting for its PaaS project to become active (`Retry-After: 10`). Retrying succeeds once it is. */
            503: {
                headers: {
                    "Retry-After": components["headers"]["RetryAfter"];
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
